using System;
using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Typed metadata for Person: {personInfo.Type.Name}");

// Prove it works — serialize via the typed metadata
string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if not resolvable
bool found = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGetTypeInfo(Person): found={found}, type={info?.Type.Name}");

// Now try a type that the resolver *can* resolve (DefaultJsonTypeInfoResolver
// handles all types), so let's demo with a resolver that only handles Person:
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new PersonOnlyResolver()
};

bool foundPerson = restrictedOptions.TryGetTypeInfo(typeof(Person), out _);
bool foundOrder  = restrictedOptions.TryGetTypeInfo(typeof(Order), out _);
Console.WriteLine($"\nRestrictedResolver — Person available: {foundPerson}");
Console.WriteLine($"RestrictedResolver — Order  available: {foundOrder}");

// Records used in the demo
public record Person(string Name, int Age);
public record Order(int Id, decimal Total);

// A custom resolver that only provides metadata for Person
file sealed class PersonOnlyResolver : IJsonTypeInfoResolver
{
    private readonly DefaultJsonTypeInfoResolver _inner = new();

    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options)
        => type == typeof(Person) ? _inner.GetTypeInfo(type, options) : null;
}
EOF
